Lemma vsd_loop : forall (k : nat) ra sp gp tp t0 t1 t2 s0 s1 a2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (vb : Z),
  16 <= vb -> vb + 8 * Z.of_nat k < 2^64 -> (1 <= k)%nat ->
  mem_inv usegs m ->
  evt usegs (vsd_loop_post ra sp gp tp t0 t1 t2 s0 s1 a2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc vb m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 vb) (Z_to_bv 64 (vb + 8 * Z.of_nat k)) a2 (Z_to_bv 64 8) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_UB_VSD_LOOP) fc None m (seg_rom usegs)).
