Definition sci_segA_post (sp gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (implb lk vb vcap lo : Z) (ist : list Z) (j7 : list byte) (ra s0 s1 s2 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (Z_to_bv 64 P_SCI_DEL1_RET) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2
                  (Z_to_bv 64 (implb + 24)) (Z_to_bv 64 (implb + 32)) (Z_to_bv 64 vb) (Z_to_bv 64 (8 * vcap)) a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 1) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 ROPDEL2) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (implb + 8, implb + 12); (implb + 80, implb + 88)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -64)
    /\ rw_cells usegs m' (bv_unsigned sp + -64) [C8 (Z_to_bv 64 (implb + 72)); C8 (Z_to_bv 64 18446744073709551615); C8 (Z_to_bv 64 implb); C8 (Z_to_bv 64 P_SCS_REL_RET)]
    /\ rw_cells usegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells usegs m' implb (SpcHdrCells (mkSPC VP_SPCI_IMPL 0 1 1) j7)
    /\ PMutex m' (implb + 32) lk
    /\ rw_cells usegs m' (implb + 72) [C8 (wz vb); C8 (wz vb); C8 (wz (vb + 8 * vcap))].
Scheme kc__3 := Elimination for Corelib.Init.Logic.ex Sort Prop.

Lemma sci_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (PC implb lk vb vcap lo : Z) (ist : list Z) (j7 : list byte),
  ro_cells usegs m PC [C8 (wz implb)] -> (PC + 8 <= lo \/ bv_unsigned sp <= PC) ->
  rw_cells usegs m implb (SpcHdrCells (mkSPC VP_SPCI_IMPL 1 1 1) j7) ->
  PMutex m (implb + 32) lk ->
  rw_cells usegs m (implb + 72) [C8 (wz vb); C8 (wz (vb + 8 * zlength ist)); C8 (wz (vb + 8 * vcap))] ->
  0 < implb -> implb mod 16 = 0 -> implb + 96 <= hceil -> (implb + 96 <= 0x10000 \/ 0xb8000 <= implb) ->
  0 < vb -> vb mod 16 = 0 -> vb + 8 * vcap <= hceil -> 0 < vcap -> zlength ist <= vcap ->
  XStatics m ->
  stk usegs m lo (bv_unsigned sp) -> lo + 64 <= bv_unsigned sp -> hceil <= lo ->
  mem_inv usegs m ->
  evt usegs (sci_segA_post sp gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc implb lk vb vcap lo ist j7 ra s0 s1 s2 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 PC) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
