Definition sci_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (implb u lk lo : Z) (j7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 implb) (Z_to_bv 64 96) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 ROPDEL2) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (implb, implb + 32)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' implb (SpcHdrCells (mkSPC VP_SPCI_IMPL u 0 0) j7)
    /\ PMutex m' (implb + 32) lk.

