(* [comment removed for export] *)
(* [comment removed for export] *)

Definition SHCOUNT_DTOR_IMPL_STACK : Z := 64 + RFREE_STACK.

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  (* [comment removed for export] *)
  Lemma hh_lb_remove_nodup : forall p LB, List.NoDup (map blk_id LB) -> List.NoDup (map blk_id (hs_lb_remove H p LB)).
  Proof.
    intros p LB. induction LB as [|b LB IH]; intros ND.
    - cbn. destruct (hs_lb_remove H p []) as [|c l] eqn:E; [constructor|].
      exfalso. pose proof (hh_lb_remove_In H HH p [] c) as K. rewrite E in K. exact (K (or_introl eq_refl)).
    - cbn in ND. inversion ND as [|x l NI ND']; subst.
      destruct (bptr_eq_dec (blk_id b) p) as [E|NE].
      + destruct b as [[pb Ab] nb]. cbn in E. subst pb. rewrite (proj1 (hh_lb_remove H HH)) by exact NI. exact ND'.
      + rewrite (hh_lb_remove_cons_ne H HH) by exact NE. cbn. constructor; [| apply IH; exact ND'].
        intros K. apply NI. apply in_map_iff in K. destruct K as (c & Ec & Hc). rewrite <- Ec. apply in_map. eapply (hh_lb_remove_In H HH). exact Hc.
  Qed.

  Definition shcount_dtor_impl_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (implb vb vcap lo B : Z) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (pi q : bptr),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ In (pi, implb, SZ_SPCI_IMPL) LB /\ In (q, vb, 8 * vcap) LB
      /\ hs_RHEAP H s' (hs_lb_remove H pi (hs_lb_remove H q LB)) m'
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) [(implb, implb + 96); (vb, vb + 8 * vcap)] m m'.

  Definition shcount_dtor_impl_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (PC implb lk vb vcap lo B : Z) (ist : list Z) (errv : word),
      a0 = Z_to_bv 64 PC ->
      (* [comment removed for export] *)
      ro_cells usegs m PC [C8 (wz implb)] -> (PC + 8 <= lo \/ bv_unsigned sp <= PC) ->
      (* [comment removed for export] *)
      ImplBlock LB m implb (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 1) lk vb ist vcap) -> 0 < vcap ->
      (vb + 8 * vcap <= implb \/ implb + SZ_SPCI_IMPL <= vb) ->
      XStatics m ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
